contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        uint pre = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint preC = address(c).balance;
        uint preSelf = address(this).balance;

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint post = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint postC = address(c).balance;
        uint postSelf = address(this).balance;

        assert(post == pre + amount && postC == preC + amount && postSelf == preSelf - amount);
    }

    receive() external payable {}
}

