pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint256 pre;
        try c.getBalance(address(this)) returns (uint256 __r) { pre = __r; } catch { return; }
        uint preC = address(c).balance;
        uint preSelf = address(this).balance;
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 post;
        try c.getBalance(address(this)) returns (uint256 __r) { post = __r; } catch { return; }
        uint postC = address(c).balance;
        uint postSelf = address(this).balance;
        assertTrue(post == pre + amount && postC == preC + amount && postSelf == preSelf - amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
